// Keep the file:// browser bundle in sync with the compiled Wasm engine.
import { readFileSync, writeFileSync } from 'node:fs';
const bytes = readFileSync(new URL('../build/bridge.wasm', import.meta.url));
writeFileSync(new URL('../web/wasm_module.js', import.meta.url),
  '// Generated by npm run build; do not edit.\nwindow.BRIDGE_WASM_BASE64 = ' + JSON.stringify(bytes.toString('base64')) + ';\n');
